using System;using System.IO;using System.Linq;using System.Windows.Forms;using System.Threading;using System.Threading.Tasks;using System.Text.RegularExpressions;
class ModelPreviewTest {
 [STAThread]static int Main(string[] args){Application.EnableVisualStyles();int code=1;string temp=Path.Combine(Path.GetTempPath(),"3DSTL-preview-test-"+Guid.NewGuid());Directory.CreateDirectory(temp);using var form=new ModelPreviewForm(null,temp);form.Shown+=async(_,_)=>{try{
 foreach(var file in args){await form.LoadModel(file);if(!form.PreviewReady||!form.Text.Contains(Path.GetFileName(file)))throw new Exception("Preview failed: "+file);Console.WriteLine("PASS displayed "+Path.GetFileName(file));}
 await form.LoadModel(Path.Combine(temp,"missing.stl"));if(form.PreviewReady)throw new Exception("Missing file reported ready");var lang=form.Controls.OfType<FlowLayoutPanel>().Single().Controls.OfType<ComboBox>().Single();lang.SelectedIndex=1;foreach(var label in form.Controls.OfType<Label>())if(Regex.IsMatch(label.Text,@"[\u4e00-\u9fff]"))throw new Exception("Error did not translate");
 string damaged=Path.Combine(temp,"damaged.stl");File.WriteAllText(damaged,"not a model");await form.LoadModel(damaged);if(form.PreviewReady||!File.Exists(Path.Combine(temp,"preview-error.log"))||!File.ReadAllText(Path.Combine(temp,"preview-error.log")).Contains("InvalidDataException"))throw new Exception("Failed render did not produce local diagnostics");
 await form.LoadModel(args[0]);if(!form.PreviewReady)throw new Exception("Cannot recover after failure");using(var capture=new System.Drawing.Bitmap(form.Width,form.Height)){form.DrawToBitmap(capture,new System.Drawing.Rectangle(System.Drawing.Point.Empty,capture.Size));capture.Save("artifacts/certification-20261021/preview-en.png");}
 using(var cancel=new CancellationTokenSource()){cancel.Cancel();bool stopped=false;try{using var image=await ModelPreviewForm.RenderImage(args[0],cancel.Token);}catch(OperationCanceledException){stopped=true;}if(!stopped)throw new Exception("Cancelled job launched");}
 string folderCase=Path.Combine(temp,"folder-case");Directory.CreateDirectory(folderCase);File.Copy(args[0],Path.Combine(folderCase,"valid"+Path.GetExtension(args[0])));File.WriteAllText(Path.Combine(folderCase,"broken.stl"),"bad");
 using(var folderForm=new FolderPreviewForm()){folderForm.Show();await folderForm.Generate(folderCase);if(!folderForm.Controls.OfType<Label>().Single().Text.Contains("Failed: 1"))throw new Exception("Folder failure summary missing");using(var snap=new System.Drawing.Bitmap(folderForm.Width,folderForm.Height)){folderForm.DrawToBitmap(snap,new System.Drawing.Rectangle(System.Drawing.Point.Empty,snap.Size));snap.Save("artifacts/nas-update/folder-progress.png");}var cancelled=folderForm.Generate(folderCase);folderForm.Controls.OfType<FlowLayoutPanel>().Single().Controls.OfType<Button>().Last().PerformClick();await cancelled;if(!folderForm.Controls.OfType<Label>().Single().Text.Contains("Cancelled"))throw new Exception("Folder cancellation failed");folderForm.Close();}
 Console.WriteLine("PASS folder queue, failure feedback, completion and cancellation");
 Console.WriteLine("PASS repeated loads, missing-file feedback, error language switch, recovery and cancellation");code=0;
 }catch(Exception e){Console.Error.WriteLine(e);}finally{form.Close();}};Application.Run(form);Directory.Delete(temp,true);return code;}
}
